fn xdf_format_fields(format: HexDisplayFormat) -> Result<(usize, bool, NumericKind), String> {
    Ok(match format {
        HexDisplayFormat::Bytes | HexDisplayFormat::Unsigned8 => (8, false, NumericKind::Integer),
        HexDisplayFormat::Signed8 => (8, true, NumericKind::Integer),
        HexDisplayFormat::Unsigned16 => (16, false, NumericKind::Integer),
        HexDisplayFormat::Signed16 => (16, true, NumericKind::Integer),
        HexDisplayFormat::Unsigned32 => (32, false, NumericKind::Integer),
        HexDisplayFormat::Signed32 => (32, true, NumericKind::Integer),
        HexDisplayFormat::Unsigned64 => (64, false, NumericKind::Integer),
        HexDisplayFormat::Signed64 => (64, true, NumericKind::Integer),
        HexDisplayFormat::Float32 => (32, false, NumericKind::Ieee754Binary32),
        HexDisplayFormat::Float64 => {
            return Err(
                "Float64 XDF storage is not verified; choose an integer or Float32 format.".into(),
            )
        }
    })
}

fn xdf_endianness(endianness: HexEndianness) -> Endianness {
    match endianness {
        HexEndianness::Little => Endianness::Little,
        HexEndianness::Big => Endianness::Big,
    }
}

fn parse_xdf_address_ui(value: &str) -> Result<u64, String> {
    let value = value.trim();
    let digits = value
        .strip_prefix("0x")
        .or_else(|| value.strip_prefix("0X"))
        .unwrap_or(value);
    let radix = if digits.len() != value.len() || digits.chars().any(|c| c.is_ascii_alphabetic()) {
        16
    } else {
        10
    };
    u64::from_str_radix(digits, radix).map_err(|_| format!("Invalid XDF address: {value}"))
}

fn translate_xdf_address_ui(
    address: u64,
    base_offset: u64,
    subtract: bool,
) -> Result<usize, String> {
    let translated = if subtract {
        address.checked_sub(base_offset)
    } else {
        address.checked_add(base_offset)
    }
    .ok_or_else(|| "XDF base offset produces an address outside BIN space.".to_string())?;
    usize::try_from(translated)
        .map_err(|_| "XDF address does not fit this platform's BIN offset range.".to_string())
}

fn proposed_parameter_draft(
    proposed: &ProposedXdfParameter,
    previous: Option<&XdfParameterDraft>,
) -> XdfParameterDraft {
    let axes = proposed
        .axes
        .iter()
        .map(|axis| {
            let old_axis = previous.and_then(|previous| {
                previous
                    .axes
                    .iter()
                    .find(|candidate| candidate.id == axis.id)
            });
            let mut metadata = old_axis.map_or(
                AxisMetadata {
                    units: None,
                    unit_type: None,
                    decimal_places: None,
                    min: None,
                    max: None,
                    output_type: None,
                },
                |old| old.metadata.clone(),
            );
            metadata.units = axis.units.clone();
            metadata.decimal_places = axis.decimal_places;
            XdfAxisDraft {
                id: axis.id.clone(),
                title: axis.title.clone(),
                count: axis.count,
                address: axis.xdf_address,
                element_width_bits: axis.element_width_bits,
                stride_bits: axis.stride_bits,
                signed: axis.signed,
                endianness: match axis.endianness {
                    ProposedEndianness::Little => Endianness::Little,
                    ProposedEndianness::Big => Endianness::Big,
                },
                numeric_kind: match axis.numeric_kind {
                    ProposedNumericKind::Integer => NumericKind::Integer,
                    ProposedNumericKind::Ieee754Binary32 => NumericKind::Ieee754Binary32,
                },
                unknown_type_flags: old_axis.map_or(0, |old| old.unknown_type_flags),
                conversion: axis.conversion.clone(),
                metadata,
                labels: axis
                    .labels
                    .iter()
                    .enumerate()
                    .map(|(index, value)| AxisLabel {
                        index,
                        value: value.clone(),
                    })
                    .collect(),
            }
        })
        .collect();
    XdfParameterDraft {
        unique_id: proposed.unique_id.clone(),
        kind: match proposed.kind {
            ProposedXdfParameterKind::Constant => ParameterKind::Constant,
            ProposedXdfParameterKind::Table => ParameterKind::Table,
            ProposedXdfParameterKind::BitField => ParameterKind::BitField,
            ProposedXdfParameterKind::Flag => ParameterKind::Flag,
        },
        title: proposed.title.clone(),
        description: proposed.description.clone(),
        category: proposed.category.clone(),
        category_memberships: previous
            .map_or_else(Vec::new, |previous| previous.category_memberships.clone()),
        xdf_address: proposed.xdf_address,
        element_width_bits: proposed.element_width_bits,
        dimensions: tuner_xdf::Dimensions {
            rows: proposed.rows,
            columns: proposed.columns,
        },
        signed: proposed.signed,
        endianness: match proposed.endianness {
            ProposedEndianness::Little => Endianness::Little,
            ProposedEndianness::Big => Endianness::Big,
        },
        numeric_kind: match proposed.numeric_kind {
            ProposedNumericKind::Integer => NumericKind::Integer,
            ProposedNumericKind::Ieee754Binary32 => NumericKind::Ieee754Binary32,
        },
        column_major: proposed.column_major,
        row_stride_bits: proposed.row_stride_bits,
        column_stride_bits: proposed.column_stride_bits,
        conversion: proposed.conversion.clone(),
        bit_offset: proposed.bit_offset,
        bit_width: proposed.bit_width,
        bit_mask: proposed.bit_mask,
        unknown_type_flags: previous.map_or(0, |previous| previous.unknown_type_flags),
        axes,
    }
}
const TABLE_BODY_FONT_SIZE: f32 = 14.0;

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TableUiScale {
    pub factor: f32,
    pub cell_width: f32,
    pub cell_height: f32,
    pub body_font_size: f32,
}

pub fn table_ui_scale(zoom_percent: u16) -> TableUiScale {
    let factor = f32::from(zoom_percent.clamp(50, 200)) / 100.0;
    TableUiScale {
        factor,
        cell_width: TABLE_CELL_WIDTH * factor,
        cell_height: TABLE_CELL_HEIGHT * factor,
        body_font_size: TABLE_BODY_FONT_SIZE * factor,
    }
}

fn effective_table_compare_mode(
    source_available: bool,
    selected_semantic_id: Option<&str>,
    semantic_id: &str,
    mode: CompareValueMode,
) -> CompareValueMode {
    if source_available && selected_semantic_id == Some(semantic_id) {
        mode
    } else {
        CompareValueMode::Destination
    }
}

fn table_needs_destination_views(
    kind: ParameterKind,
    mode: CompareValueMode,
    compare_range_available: bool,
) -> bool {
    kind == ParameterKind::Table
        && (mode == CompareValueMode::Destination || !compare_range_available)
}

fn compile_axis_conversion(
    parameter: &ParameterDefinition,
    axis_index: usize,
) -> Result<Conversion, String> {
    let axis = parameter
        .axis_definition(axis_index)
        .map_err(|error| error.to_string())?;
    Conversion::parse(axis.conversion.as_deref().unwrap_or("X"))
        .map_err(|error| format!("engineering conversion failed: {error}"))
}

fn compare_mode_label(mode: CompareValueMode) -> &'static str {
    match mode {
        CompareValueMode::Destination => "Destination",
        CompareValueMode::Source => "Compare",
        CompareValueMode::AbsoluteDelta => "Delta",
        CompareValueMode::PercentDelta => "% Delta",
    }
}

fn parse_hex_display_format(value: &str) -> Option<HexDisplayFormat> {
    Some(match value.trim().to_ascii_lowercase().as_str() {
        "bytes" | "hex" => HexDisplayFormat::Bytes,
        "u8" | "uint8" => HexDisplayFormat::Unsigned8,
        "i8" | "int8" => HexDisplayFormat::Signed8,
        "u16" | "uint16" => HexDisplayFormat::Unsigned16,
        "i16" | "int16" => HexDisplayFormat::Signed16,
        "u32" | "uint32" => HexDisplayFormat::Unsigned32,
        "i32" | "int32" => HexDisplayFormat::Signed32,
        "u64" | "uint64" => HexDisplayFormat::Unsigned64,
        "i64" | "int64" => HexDisplayFormat::Signed64,
        "f32" | "float32" => HexDisplayFormat::Float32,
        "f64" | "float64" => HexDisplayFormat::Float64,
        _ => return None,
    })
}

fn parse_hex_endianness(value: &str) -> Option<HexEndianness> {
    match value.trim().to_ascii_lowercase().as_str() {
        "little" | "little_endian" => Some(HexEndianness::Little),
        "big" | "big_endian" => Some(HexEndianness::Big),
        _ => None,
    }
}

fn parse_hex_color_mode(value: &str) -> Option<TableColorMode> {
    match value.trim().to_ascii_lowercase().as_str() {
        "off" => Some(TableColorMode::Off),
        "auto" | "auto_range" => Some(TableColorMode::AutoRange),
        "fixed" | "fixed_range" => Some(TableColorMode::FixedRange),
        _ => None,
    }
}

fn parse_hex_auto_range_scope(value: &str) -> Option<HexAutoRangeScope> {
    match value.trim().to_ascii_lowercase().as_str() {
        "visible" | "visible_percentile" => Some(HexAutoRangeScope::VisiblePercentile),
        "whole_bin" => Some(HexAutoRangeScope::WholeBin),
        _ => None,
    }
}

fn quick_action_button_with_help(
    ui: &mut egui::Ui,
    icon: &str,
    tooltip: &str,
    enabled: bool,
    fill: egui::Color32,
    school_me_mode: bool,
    help_id: school_help::SchoolHelpId,
) -> bool {
    let response = quick_action_button_response(ui, icon, enabled, fill);
    if school_me_mode {
        school_help::show_custom_for_response(ui.ctx(), &response, true, help_id);
    } else {
        response.clone().on_hover_text(tooltip);
    }
    response.clicked()
}

fn quick_action_button_response(
    ui: &mut egui::Ui,
    icon: &str,
    enabled: bool,
    fill: egui::Color32,
) -> egui::Response {
    ui.add_enabled(
        enabled,
        egui::Button::new(
            egui::RichText::new(icon)
                .strong()
                .color(egui::Color32::WHITE),
        )
        .small()
        .fill(fill)
        .stroke(egui::Stroke::new(1.0, fill.gamma_multiply(1.35))),
    )
}

fn scale_margin(margin: egui::Margin, factor: f32) -> egui::Margin {
    let scale = |value: i8| {
        (f32::from(value) * factor)
            .round()
            .clamp(f32::from(i8::MIN), f32::from(i8::MAX)) as i8
    };
    egui::Margin {
        left: scale(margin.left),
        right: scale(margin.right),
        top: scale(margin.top),
        bottom: scale(margin.bottom),
    }
}

fn scale_table_style(style: &mut egui::Style, scale: TableUiScale) {
    for font in style.text_styles.values_mut() {
        font.size *= scale.factor;
    }
    style.spacing.item_spacing *= scale.factor;
    style.spacing.window_margin = scale_margin(style.spacing.window_margin, scale.factor);
    style.spacing.button_padding *= scale.factor;
    style.spacing.menu_margin = scale_margin(style.spacing.menu_margin, scale.factor);
    style.spacing.indent *= scale.factor;
    style.spacing.interact_size *= scale.factor;
    style.spacing.slider_width *= scale.factor;
    style.spacing.slider_rail_height *= scale.factor;
    style.spacing.combo_width *= scale.factor;
    style.spacing.text_edit_width *= scale.factor;
    style.spacing.extra_text_line_spacing *= scale.factor;
    style.spacing.icon_width *= scale.factor;
    style.spacing.icon_width_inner *= scale.factor;
    style.spacing.icon_spacing *= scale.factor;
    style.spacing.default_area_size *= scale.factor;
    style.spacing.tooltip_width *= scale.factor;
    style.spacing.menu_width *= scale.factor;
    style.spacing.menu_spacing *= scale.factor;
    style.spacing.combo_height *= scale.factor;
    style.spacing.scroll.content_margin =
        scale_margin(style.spacing.scroll.content_margin, scale.factor);
    style.spacing.scroll.bar_width *= scale.factor;
    style.spacing.scroll.handle_min_length *= scale.factor;
    style.spacing.scroll.bar_inner_margin *= scale.factor;
    style.spacing.scroll.bar_outer_margin *= scale.factor;
    style.spacing.scroll.floating_width *= scale.factor;
    style.spacing.scroll.floating_allocated_width *= scale.factor;
}

