#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(default)]
pub struct TableColorSettings {
    pub mode: TableColorMode,
    pub low: [u8; 4],
    pub middle: [u8; 4],
    pub high: [u8; 4],
    pub fixed_min: Option<f64>,
    pub fixed_max: Option<f64>,
}

impl Default for TableColorSettings {
    fn default() -> Self {
        Self {
            mode: TableColorMode::AutoRange,
            low: [32, 76, 144, 190],
            middle: [180, 128, 38, 190],
            high: [168, 52, 48, 190],
            fixed_min: None,
            fixed_max: None,
        }
    }
}

impl TableColorSettings {
    pub fn sanitize(&mut self) {
        if self.fixed_min.is_some_and(|value| !value.is_finite()) {
            self.fixed_min = None;
        }
        if self.fixed_max.is_some_and(|value| !value.is_finite()) {
            self.fixed_max = None;
        }
        if let (Some(minimum), Some(maximum)) = (self.fixed_min, self.fixed_max) {
            if minimum >= maximum {
                self.fixed_max = None;
            }
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TableAxisRole {
    X,
    Y,
}

impl TableAxisRole {
    fn explicit_ids(self) -> &'static [&'static str] {
        match self {
            Self::X => &["x", "column", "columns"],
            Self::Y => &["y", "row", "rows"],
        }
    }

    fn positional_index(self) -> usize {
        match self {
            Self::X => 0,
            Self::Y => 1,
        }
    }

    fn position_label(self) -> &'static str {
        match self {
            Self::X => "C",
            Self::Y => "R",
        }
    }
}

pub fn table_axis_index(
    parameter: &ParameterDefinition,
    role: TableAxisRole,
    expected_count: usize,
) -> Option<usize> {
    if parameter.axes.len() == 1 && parameter.axes[0].id.trim().eq_ignore_ascii_case("z") {
        return None;
    }
    let ids = role.explicit_ids();
    let explicit_id_present = parameter
        .axes
        .iter()
        .any(|axis| ids.iter().any(|id| axis.id.trim().eq_ignore_ascii_case(id)));
    for id in ids {
        if let Some((index, _)) = parameter.axes.iter().enumerate().find(|(_, axis)| {
            axis.count == expected_count && axis.id.trim().eq_ignore_ascii_case(id)
        }) {
            return Some(index);
        }
    }
    if explicit_id_present {
        return None;
    }
    let positional_index = role.positional_index();
    parameter
        .axes
        .get(positional_index)
        .filter(|axis| axis.count == expected_count)
        .map(|_| positional_index)
}

