#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(default)]
pub struct TableWindowMemory {
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
    #[serde(default = "crate::window_geometry::legacy_position_saved")]
    pub position_saved: bool,
    pub zoom_percent: u16,
    pub scroll_x: u32,
    pub scroll_y: u32,
    pub decimal_places: u8,
    pub coloring: TableColorSettings,
    /// `Some(true)` keeps the border fitted to the table at the saved zoom.
    /// `Some(false)` preserves a size chosen by the user. `None` is an old
    /// settings file and is resolved conservatively when the table opens.
    #[serde(default)]
    pub fit_to_content: Option<bool>,
}

impl Default for TableWindowMemory {
    fn default() -> Self {
        Self {
            x: 80,
            y: 80,
            width: 760,
            height: 520,
            position_saved: false,
            zoom_percent: 100,
            scroll_x: 0,
            scroll_y: 0,
            decimal_places: 2,
            coloring: TableColorSettings::default(),
            fit_to_content: Some(true),
        }
    }
}

impl TableWindowMemory {
    fn sanitize(&mut self) {
        self.width = self
            .width
            .clamp(TABLE_WINDOW_MIN_WIDTH, TABLE_WINDOW_MAX_WIDTH);
        self.height = self
            .height
            .clamp(TABLE_WINDOW_MIN_HEIGHT, TABLE_WINDOW_MAX_HEIGHT);
        self.zoom_percent = self.zoom_percent.clamp(50, 200);
        self.decimal_places = self.decimal_places.clamp(0, 8);
        self.coloring.sanitize();
    }
}

#[cfg(test)]
fn color_ramp_samples(
    settings: &TableColorSettings,
    observed_range: (f64, f64),
    values: &[f64],
) -> Vec<egui::Color32> {
    values
        .iter()
        .copied()
        .map(|value| table_cell_fill(settings, value, Some(observed_range)))
        .map(|color| color.unwrap_or(egui::Color32::TRANSPARENT))
        .collect()
}

fn raw_value_as_f64(value: RawValue) -> f64 {
    match value {
        RawValue::Unsigned(value) => value as f64,
        RawValue::Signed(value) => value as f64,
        RawValue::Float32Bits(bits) => f32::from_bits(bits) as f64,
    }
}

fn table_numeric_value(view: &CellView, display: TableDisplay) -> Option<f64> {
    let value = match display {
        TableDisplay::Engineering => view
            .engineering
            .filter(|value| value.is_finite())
            .unwrap_or_else(|| raw_value_as_f64(view.raw)),
        TableDisplay::Raw => raw_value_as_f64(view.raw),
    };
    value.is_finite().then_some(value)
}

fn axis_numeric_value(view: AxisView) -> Option<f64> {
    view.engineering
        .filter(|value| value.is_finite())
        .or_else(|| {
            view.raw
                .map(raw_value_as_f64)
                .filter(|value| value.is_finite())
        })
}

fn table_value_range(
    views: &[Result<CellView, WorkspaceError>],
    display: TableDisplay,
) -> Option<(f64, f64)> {
    let mut values = Vec::new();
    for view in views.iter().flatten() {
        if let Some(value) = table_numeric_value(view, display) {
            values.push(value);
        }
    }
    color_range_for_values(&values)
}

fn surface_range_for_memory(
    data: &SurfaceData,
    memory: &SurfaceViewMemory,
) -> Option<SurfaceRange> {
    let automatic = auto_surface_range(data.values.iter().flatten().copied())?;
    if memory.auto_range {
        return Some(automatic);
    }
    match (memory.fixed_min, memory.fixed_max) {
        (Some(minimum), Some(maximum)) if minimum.is_finite() && minimum < maximum => {
            Some(SurfaceRange { minimum, maximum })
        }
        _ => Some(automatic),
    }
}

const TABLE_GEOMETRY_STABLE_OBSERVATIONS: u8 = 2;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct TableGeometry {
    x: i32,
    y: i32,
    width: u32,
    height: u32,
}

impl TableGeometry {
    fn from_memory(memory: &TableWindowMemory) -> Self {
        Self {
            x: memory.x,
            y: memory.y,
            width: memory.width,
            height: memory.height,
        }
    }

    fn from_rect(rect: egui::Rect) -> Self {
        Self {
            x: rect.min.x.round() as i32,
            y: rect.min.y.round() as i32,
            width: rect.width().round().max(0.0) as u32,
            height: rect.height().round().max(0.0) as u32,
        }
    }

    fn position(self) -> egui::Pos2 {
        egui::pos2(self.x as f32, self.y as f32)
    }

    fn size(self) -> egui::Vec2 {
        egui::vec2(self.width as f32, self.height as f32)
    }
}

fn table_effective_geometry(saved: TableGeometry, canvas_rect: egui::Rect) -> TableGeometry {
    let rect = egui::Rect::from_min_size(saved.position(), saved.size());
    TableGeometry::from_rect(clamp_rect(rect, canvas_rect, egui::Vec2::ZERO))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct TableGeometryGuard {
    geometry: TableGeometry,
    stable_observations: u8,
}

impl TableGeometryGuard {
    fn new(geometry: TableGeometry) -> Self {
        Self {
            geometry,
            stable_observations: 0,
        }
    }
}

fn advance_table_geometry_guard(
    guard: TableGeometryGuard,
    observed: Option<TableGeometry>,
    pointer_down: bool,
) -> Option<TableGeometryGuard> {
    if pointer_down {
        return Some(TableGeometryGuard {
            stable_observations: 0,
            ..guard
        });
    }

    if observed == Some(guard.geometry) {
        let stable_observations = guard.stable_observations.saturating_add(1);
        if stable_observations >= TABLE_GEOMETRY_STABLE_OBSERVATIONS {
            return None;
        }
        Some(TableGeometryGuard {
            stable_observations,
            ..guard
        })
    } else {
        Some(TableGeometryGuard {
            stable_observations: 0,
            ..guard
        })
    }
}

fn table_default_window_size(
    rows: usize,
    columns: usize,
    zoom_percent: u16,
    title: &str,
) -> egui::Vec2 {
    let scale = table_ui_scale(zoom_percent);
    let grid_width = TABLE_ROW_LABEL_WIDTH * scale.factor
        + columns as f32 * scale.cell_width
        + 36.0 * scale.factor;
    let title_width = title.chars().count() as f32 * 7.5 * scale.factor + 84.0 * scale.factor;
    let width = grid_width
        .max(title_width)
        .clamp(TABLE_WINDOW_MIN_WIDTH as f32, TABLE_WINDOW_MAX_WIDTH as f32);

    let grid_height = rows.saturating_add(1) as f32 * scale.cell_height + 12.0 * scale.factor;
    let height = (grid_height + 104.0 * scale.factor).clamp(
        TABLE_WINDOW_MIN_HEIGHT as f32,
        TABLE_WINDOW_MAX_HEIGHT as f32,
    );
    egui::vec2(width.ceil(), height.ceil())
}

fn default_table_window_memory(
    summary: &ParameterSummary,
    category: &str,
    zoom_percent: u16,
) -> TableWindowMemory {
    let title = format!("{category} · {}", summary_label(summary));
    let size = table_default_window_size(summary.rows, summary.columns, zoom_percent, &title);
    let mut memory = TableWindowMemory {
        width: size.x as u32,
        height: size.y as u32,
        zoom_percent: zoom_percent.clamp(50, 200),
        ..TableWindowMemory::default()
    };
    memory.sanitize();
    memory
}

fn table_memory_matches_default_size(
    memory: &TableWindowMemory,
    summary: &ParameterSummary,
    category: &str,
) -> bool {
    let title = format!("{category} · {}", summary_label(summary));
    let current_default = table_default_window_size(summary.rows, summary.columns, 100, &title);
    let legacy_default = TableWindowMemory::default();
    (memory.width, memory.height) == (current_default.x as u32, current_default.y as u32)
        || (memory.width, memory.height) == (legacy_default.width, legacy_default.height)
}

fn prepare_table_memory_for_open(
    mut memory: TableWindowMemory,
    summary: &ParameterSummary,
    category: &str,
) -> TableWindowMemory {
    let fit_to_content = memory
        .fit_to_content
        .unwrap_or_else(|| table_memory_matches_default_size(&memory, summary, category));
    memory.fit_to_content = Some(fit_to_content);
    if fit_to_content {
        let title = format!("{category} · {}", summary_label(summary));
        let size =
            table_default_window_size(summary.rows, summary.columns, memory.zoom_percent, &title);
        memory.width = size.x as u32;
        memory.height = size.y as u32;
    }
    memory.sanitize();
    memory
}

