#[derive(Default)]
struct EngineeringQuantizationSummary {
    count: usize,
    example: Option<EngineeringWriteResult>,
}

impl EngineeringQuantizationSummary {
    fn from_result(result: EngineeringWriteResult) -> Self {
        let mut summary = Self::default();
        summary.record(result);
        summary
    }

    fn record(&mut self, result: EngineeringWriteResult) {
        let integer_storage = matches!(
            result.raw_value,
            RawValue::Unsigned(_) | RawValue::Signed(_)
        );
        let scale = result
            .requested_engineering
            .abs()
            .max(result.stored_engineering.abs())
            .max(1.0);
        let meaningful_difference = (result.requested_engineering - result.stored_engineering)
            .abs()
            > f64::EPSILON * scale * 8.0;
        if integer_storage && meaningful_difference {
            self.count += 1;
            self.example.get_or_insert(result);
        }
    }

    fn status_note(&self) -> String {
        let Some(example) = self.example else {
            return String::new();
        };
        if self.count == 1 {
            format!(
                " Rounded to the nearest raw integer: requested {:.12}, stored {:.12} ({}).",
                example.requested_engineering,
                example.stored_engineering,
                raw_value_text(example.raw_value)
            )
        } else {
            format!(
                " Rounded {} integer-backed values to the nearest raw integer; example: requested {:.12}, stored {:.12} ({}).",
                self.count,
                example.requested_engineering,
                example.stored_engineering,
                raw_value_text(example.raw_value)
            )
        }
    }
}

