impl ProjectPreferences {
    pub fn for_identity(identity: impl Into<String>) -> Self {
        Self {
            bin_identity: identity.into(),
            ..Self::default()
        }
    }

    fn sanitize(&mut self) {
        let legacy_geometry = self.version < PROJECT_SETTINGS_VERSION;
        if legacy_geometry {
            let compare_default = CompareWindowMemory::default();
            if !self.dock_state.is_open_tool(&WindowId::Compare)
                && (
                    self.compare_window.x,
                    self.compare_window.y,
                    self.compare_window.width,
                    self.compare_window.height,
                ) == (
                    compare_default.x,
                    compare_default.y,
                    compare_default.width,
                    compare_default.height,
                )
            {
                self.compare_window.position_saved = false;
            }
            let hex_default = HexWindowMemory::default();
            if !self.hex_window_open
                && (
                    self.hex_window.x,
                    self.hex_window.y,
                    self.hex_window.width,
                    self.hex_window.height,
                ) == (
                    hex_default.x,
                    hex_default.y,
                    hex_default.width,
                    hex_default.height,
                )
            {
                self.hex_window.position_saved = false;
            }
            let map_default = MapFinderMemory::default();
            if !self.map_finder.window_open
                && (
                    self.map_finder.x,
                    self.map_finder.y,
                    self.map_finder.width,
                    self.map_finder.height,
                ) == (
                    map_default.x,
                    map_default.y,
                    map_default.width,
                    map_default.height,
                )
            {
                self.map_finder.position_saved = false;
            }
            let search_default = SearchWindowMemory::default();
            if !self.search_state.open
                && (
                    self.search_state.window.x,
                    self.search_state.window.y,
                    self.search_state.window.width,
                    self.search_state.window.height,
                ) == (
                    search_default.x,
                    search_default.y,
                    search_default.width,
                    search_default.height,
                )
            {
                self.search_state.window.position_saved = false;
            }
        }
        self.version = PROJECT_SETTINGS_VERSION;
        self.workspace_restore_warnings.clear();
        for item in &mut self.agent_task_history {
            item.sanitize();
        }
        let mut seen = BTreeSet::new();
        self.agent_task_history.reverse();
        self.agent_task_history.retain(|item| {
            seen.insert((
                item.task_id.clone(),
                format!("{:?}", item.status),
                item.decision.clone(),
            ))
        });
        self.agent_task_history.reverse();
        if self.agent_task_history.len() > 50 {
            self.agent_task_history
                .drain(..self.agent_task_history.len() - 50);
        }
        self.browser_width = self.browser_width.clamp(180, 640);
        self.inspector_width = self.inspector_width.clamp(220, 640);
        self.diagnostics_height = self.diagnostics_height.clamp(80, 600);
        self.browser_filter = self.browser_filter.chars().take(512).collect();
        self.compare_filter = self.compare_filter.chars().take(512).collect();
        self.hex_window.sanitize();
        self.map_finder.sanitize();
        self.utility_window_geometry
            .retain(|id, _| window_geometry::is_utility_geometry_id(id));
        for memory in self.utility_window_geometry.values_mut() {
            memory.sanitize();
        }
        if self
            .hex_selection
            .is_some_and(|selection| selection.bounds().1 <= selection.bounds().0)
        {
            self.hex_selection = None;
        }
        if self
            .compare_bin_path
            .as_ref()
            .is_some_and(|path| path.as_os_str().is_empty())
        {
            self.compare_bin_path = None;
        }
        if self
            .compare_xdf_path
            .as_ref()
            .is_some_and(|path| path.as_os_str().is_empty())
        {
            self.compare_xdf_path = None;
        }
        if self
            .compare_selected_semantic_id
            .as_ref()
            .is_some_and(|semantic_id| semantic_id.is_empty())
        {
            self.compare_selected_semantic_id = None;
        }
        self.compare_window.sanitize();
        self.compare_surface_windows
            .retain(|key, _| !key.is_empty());
        for memory in self.compare_surface_windows.values_mut() {
            memory.sanitize();
        }
        deduplicate_non_empty(&mut self.collapsed_categories);
        deduplicate_non_empty(&mut self.known_categories);
        deduplicate_non_empty(&mut self.favorite_tables);
        deduplicate_non_empty(&mut self.recent_tables);
        deduplicate_non_empty(&mut self.open_table_keys);
        if let Some(active) = &self.active_table_key {
            if active.is_empty() {
                self.active_table_key = None;
            }
        }
        self.recent_tables.truncate(32);
        self.conversion_overrides
            .retain(|key, formula| !key.trim().is_empty() && !formula.trim().is_empty());
        for formula in self.conversion_overrides.values_mut() {
            *formula = formula.chars().take(4096).collect();
        }
        deduplicate_non_empty(&mut self.open_surface_keys);
        if let Some(active) = &self.active_surface_key {
            if active.is_empty() {
                self.active_surface_key = None;
            }
        }
        for memory in self.surface_windows.values_mut() {
            memory.sanitize();
        }
        for memory in self.table_windows.values_mut() {
            memory.sanitize();
        }
        self.search_state.sanitize();
        let active_name = self.active_workspace_name.trim();
        if active_name.is_empty() || active_name.chars().count() > 64 {
            self.active_workspace_name = default_workspace_name();
            self.workspace_restore_warnings
                .push("Reset invalid active workspace name to Default".into());
        } else {
            self.active_workspace_name = active_name.to_owned();
        }
        let mut seen_ids = BTreeSet::from([self.active_workspace_id]);
        let mut seen_names = BTreeSet::from([self.active_workspace_name.to_lowercase()]);
        let mut accepted = Vec::new();
        for mut snapshot in std::mem::take(&mut self.saved_workspace_snapshots) {
            let name = snapshot.name.trim();
            if name.is_empty() || name.chars().count() > 64 {
                self.workspace_restore_warnings.push(format!(
                    "Skipped workspace {} with an empty or overlong name",
                    snapshot.id
                ));
                continue;
            }
            if !seen_ids.insert(snapshot.id) {
                self.workspace_restore_warnings
                    .push(format!("Skipped duplicate workspace ID {}", snapshot.id));
                continue;
            }
            if !seen_names.insert(name.to_lowercase()) {
                self.workspace_restore_warnings
                    .push(format!("Skipped duplicate workspace name {name}"));
                continue;
            }
            snapshot.name = name.to_owned();
            let mut snapshot_preferences =
                ProjectPreferences::for_identity(self.bin_identity.clone());
            snapshot.state.apply_to(&mut snapshot_preferences);
            snapshot_preferences.sanitize();
            snapshot.state = WorkspaceViewState::capture(&snapshot_preferences);
            accepted.push(snapshot);
        }
        self.saved_workspace_snapshots = accepted;
    }

    fn append_agent_task_history(&mut self, item: AgentTaskHistoryItem) {
        self.agent_task_history.push(item);
        self.sanitize();
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ConversionTarget {
    semantic_id: String,
    axis_index: Option<usize>,
}

impl ConversionTarget {
    fn parameter(semantic_id: impl Into<String>) -> Self {
        Self {
            semantic_id: semantic_id.into(),
            axis_index: None,
        }
    }

    fn axis(semantic_id: impl Into<String>, axis_index: usize) -> Self {
        Self {
            semantic_id: semantic_id.into(),
            axis_index: Some(axis_index),
        }
    }

    fn key(&self, xdf_fingerprint: &str) -> String {
        match self.axis_index {
            Some(index) => format!("{xdf_fingerprint}:axis:{}:{index}", self.semantic_id),
            None => format!("{xdf_fingerprint}:parameter:{}", self.semantic_id),
        }
    }
}

fn document_conversion(
    document: &XdfDocument,
    target: &ConversionTarget,
) -> Option<Option<String>> {
    let parameter = document
        .parameters
        .iter()
        .find(|parameter| parameter.semantic_id == target.semantic_id)?;
    match target.axis_index {
        Some(axis_index) => parameter
            .axes
            .get(axis_index)
            .map(|axis| axis.conversion.clone()),
        None => Some(parameter.conversion.clone()),
    }
}

fn set_document_conversion(
    document: &mut XdfDocument,
    target: &ConversionTarget,
    conversion: Option<String>,
) -> bool {
    let Some(parameter) = document
        .parameters
        .iter_mut()
        .find(|parameter| parameter.semantic_id == target.semantic_id)
    else {
        return false;
    };
    match target.axis_index {
        Some(axis_index) => {
            let Some(axis) = parameter.axes.get_mut(axis_index) else {
                return false;
            };
            axis.conversion = conversion;
        }
        None => parameter.conversion = conversion,
    }
    true
}

