pub fn preferences_to_json(preferences: &AppPreferences) -> Result<String, serde_json::Error> {
    serde_json::to_string_pretty(preferences)
}

pub fn preferences_from_json(source: &str) -> AppPreferences {
    match serde_json::from_str::<AppPreferences>(source) {
        Ok(mut preferences) if preferences.version <= SETTINGS_VERSION => {
            preferences.version = SETTINGS_VERSION;
            preferences.browser_width = preferences.browser_width.clamp(180, 640);
            preferences.inspector_width = preferences.inspector_width.clamp(220, 640);
            preferences.diagnostics_height = preferences.diagnostics_height.clamp(80, 600);
            preferences.default_table_zoom_percent =
                preferences.default_table_zoom_percent.clamp(50, 200);
            deduplicate_non_empty(&mut preferences.collapsed_categories);
            deduplicate_non_empty(&mut preferences.favorite_tables);
            deduplicate_non_empty(&mut preferences.recent_tables);
            preferences.recent_tables.truncate(32);
            deduplicate_paths(&mut preferences.recent_bins);
            preferences.recent_bins.truncate(RECENT_BIN_LIMIT);
            deduplicate_paths(&mut preferences.recent_xdfs);
            preferences.recent_xdfs.truncate(RECENT_BIN_LIMIT);
            for slot in 1..=4 {
                preferences
                    .shortcuts
                    .entry(format!("workspace.slot.{slot}"))
                    .or_insert_with(|| format!("Shift+{slot}"));
            }
            for memory in preferences.table_windows.values_mut() {
                memory.sanitize();
            }
            for background in preferences.workspace_backgrounds.values_mut() {
                background.sanitize();
            }
            preferences
        }
        _ => AppPreferences::default(),
    }
}

fn deduplicate_non_empty(values: &mut Vec<String>) {
    let mut seen = BTreeSet::new();
    values.retain(|value| !value.is_empty() && seen.insert(value.clone()));
}

fn deduplicate_paths(values: &mut Vec<PathBuf>) {
    let mut seen = BTreeSet::new();
    values.retain(|path| {
        let normalized = normalized_path_text(path);
        !normalized.is_empty() && seen.insert(normalized)
    });
}

pub fn settings_path() -> PathBuf {
    if cfg!(windows) {
        if let Some(app_data) = env::var_os("APPDATA") {
            return PathBuf::from(app_data).join(APP_NAME).join("settings.json");
        }
    } else if let Some(config_home) = env::var_os("XDG_CONFIG_HOME") {
        return PathBuf::from(config_home)
            .join(APP_NAME)
            .join("settings.json");
    }
    PathBuf::from(APP_NAME).join("settings.json")
}

fn ui_ipc_endpoint_path(settings_path: &Path) -> PathBuf {
    settings_path
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .join("ui-ipc-v1.json")
}

pub fn load_preferences(path: &Path) -> AppPreferences {
    fs::read_to_string(path)
        .map(|source| preferences_from_json(&source))
        .unwrap_or_default()
}

pub fn save_preferences(path: &Path, preferences: &AppPreferences) -> io::Result<()> {
    let encoded = preferences_to_json(preferences)
        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error))?;
    save_json_atomically(path, &encoded)
}

pub fn project_identity_for_path(path: &Path) -> String {
    let resolved = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    normalize_path_text(resolved.to_string_lossy().as_ref(), cfg!(windows))
}

fn normalized_path_text(path: &Path) -> String {
    normalize_path_text(path.to_string_lossy().as_ref(), cfg!(windows))
}

fn normalize_path_text(text: &str, windows: bool) -> String {
    if windows {
        let mut normalized = text.replace('\\', "/");
        normalized.make_ascii_lowercase();
        normalized
    } else {
        text.to_string()
    }
}

fn paths_match(left: &Path, right: &Path) -> bool {
    match (fs::canonicalize(left), fs::canonicalize(right)) {
        (Ok(left), Ok(right)) => normalized_path_text(&left) == normalized_path_text(&right),
        _ => normalized_path_text(left) == normalized_path_text(right),
    }
}

fn xdf_paths_match(left: &Path, right: &Path) -> bool {
    paths_match(left, right)
}

pub fn project_settings_path(settings_path: &Path, bin_identity: &str) -> PathBuf {
    let root = settings_path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from(APP_NAME));
    root.join("projects")
        .join(format!("{}.json", sha256_hex(bin_identity.as_bytes())))
}

fn project_preferences_from_json(source: &str, bin_identity: &str) -> ProjectPreferences {
    match serde_json::from_str::<ProjectPreferences>(source) {
        Ok(mut preferences)
            if preferences.version <= PROJECT_SETTINGS_VERSION
                && preferences.bin_identity == bin_identity =>
        {
            preferences.sanitize();
            preferences
        }
        _ => ProjectPreferences::for_identity(bin_identity),
    }
}

pub fn load_project_preferences(path: &Path, bin_identity: &str) -> ProjectPreferences {
    fs::read_to_string(path)
        .map(|source| project_preferences_from_json(&source, bin_identity))
        .unwrap_or_else(|_| ProjectPreferences::for_identity(bin_identity))
}

fn pending_project_restore(
    settings_path: &Path,
    preferences: &AppPreferences,
) -> Option<PendingProjectRestore> {
    let bin_path = preferences
        .recent_bins
        .first()
        .cloned()
        .filter(|path| !path.as_os_str().is_empty())?;
    let identity = project_identity_for_path(&bin_path);
    let project =
        load_project_preferences(&project_settings_path(settings_path, &identity), &identity);
    let xdf_available = project.last_xdf_path.as_deref().is_some_and(Path::is_file);
    Some(PendingProjectRestore {
        bin_available: bin_path.is_file(),
        xdf_path: project.last_xdf_path,
        xdf_available,
        bin_path,
    })
}

pub fn save_project_preferences(path: &Path, preferences: &ProjectPreferences) -> io::Result<()> {
    let mut bounded = preferences.clone();
    bounded.sanitize();
    let encoded = serde_json::to_string_pretty(&bounded)
        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error))?;
    save_json_atomically(path, &encoded)
}

fn save_json_atomically(path: &Path, encoded: &str) -> io::Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        fs::create_dir_all(parent)?;
    }
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("settings.json");
    let temporary = path.with_file_name(format!("{file_name}.tmp-{}", std::process::id()));
    fs::write(&temporary, encoded.as_bytes())?;
    if !path.exists() {
        if let Err(error) = fs::rename(&temporary, path) {
            let _ = fs::remove_file(&temporary);
            return Err(error);
        }
        return Ok(());
    }

    let backup = path.with_file_name(format!("{file_name}.backup-{}", std::process::id()));
    if backup.exists() {
        fs::remove_file(&backup)?;
    }
    if let Err(error) = fs::rename(path, &backup) {
        let _ = fs::remove_file(&temporary);
        return Err(error);
    }
    if let Err(error) = fs::rename(&temporary, path) {
        let _ = fs::rename(&backup, path);
        let _ = fs::remove_file(&temporary);
        return Err(error);
    }
    let _ = fs::remove_file(&backup);
    Ok(())
}

