#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct CellSelection {
    pub anchor: (usize, usize),
    pub focus: (usize, usize),
}

impl CellSelection {
    pub const fn new(anchor: (usize, usize), focus: (usize, usize)) -> Self {
        Self { anchor, focus }
    }

    pub fn bounds(self) -> (usize, usize, usize, usize) {
        (
            self.anchor.0.min(self.focus.0),
            self.anchor.1.min(self.focus.1),
            self.anchor.0.max(self.focus.0),
            self.anchor.1.max(self.focus.1),
        )
    }

    pub fn contains(self, row: usize, column: usize) -> bool {
        let (top, left, bottom, right) = self.bounds();
        (top..=bottom).contains(&row) && (left..=right).contains(&column)
    }

    pub fn cell_count(self) -> usize {
        let (top, left, bottom, right) = self.bounds();
        bottom
            .saturating_sub(top)
            .saturating_add(1)
            .saturating_mul(right.saturating_sub(left).saturating_add(1))
    }
}

