/// An engineering-unit operation applied to every cell in the current rectangular selection.
///
/// Operations are deliberately expressed in engineering units so the same action remains
/// meaningful when a table uses scaling, offsets, signed storage, or floating-point storage.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum CellOperation {
    Fill(f64),
    SetZero,
    Add(f64),
    Multiply(f64),
    Clamp { min: f64, max: f64 },
}

impl CellOperation {
    fn label(self) -> &'static str {
        match self {
            Self::Fill(_) => "Filled",
            Self::SetZero => "Set zero in",
            Self::Add(_) => "Added an offset to",
            Self::Multiply(_) => "Multiplied",
            Self::Clamp { .. } => "Clamped",
        }
    }

    fn validate(self) -> Result<(), String> {
        match self {
            Self::Fill(value) if !value.is_finite() => {
                Err("Fill value must be finite.".to_string())
            }
            Self::Add(value) if !value.is_finite() => Err("Add offset must be finite.".to_string()),
            Self::Multiply(value) if !value.is_finite() => {
                Err("Multiply factor must be finite.".to_string())
            }
            Self::Clamp { min, max } if !min.is_finite() || !max.is_finite() => {
                Err("Clamp limits must be finite.".to_string())
            }
            Self::Clamp { min, max } if min > max => {
                Err("Clamp minimum cannot be greater than its maximum.".to_string())
            }
            _ => Ok(()),
        }
    }

    fn target_value(self, current: f64) -> Result<f64, String> {
        self.validate()?;
        let target = match self {
            Self::Fill(value) => value,
            Self::SetZero => 0.0,
            Self::Add(offset) => current + offset,
            Self::Multiply(factor) => current * factor,
            Self::Clamp { min, max } => current.clamp(min, max),
        };
        if target.is_finite() {
            Ok(target)
        } else {
            Err("Cell operation produced a non-finite engineering value.".to_string())
        }
    }
}

