fn surface_value_drag_targets(
    points: &[SurfacePoint],
    selection: CellSelection,
    memory: &SurfaceViewMemory,
    chart_rect: egui::Rect,
    range: SurfaceRange,
    start: egui::Pos2,
    current: egui::Pos2,
    soft_pull: bool,
    conversion: Option<&Conversion>,
    integer_storage: bool,
) -> Option<Vec<(usize, usize, f64)>> {
    let delta = surface_engineering_delta(memory, chart_rect, range, current - start)?;
    let selected_points: Vec<_> = points
        .iter()
        .copied()
        .filter(|point| selection.contains(point.row, point.column))
        .collect();
    let anchor = selected_points.iter().copied().min_by(|left, right| {
        let left_distance = (left.position - current).length_sq();
        let right_distance = (right.position - current).length_sq();
        left_distance
            .partial_cmp(&right_distance)
            .unwrap_or(std::cmp::Ordering::Equal)
    })?;
    let reference_distance = selected_points
        .iter()
        .filter(|point| (point.row, point.column) != (anchor.row, anchor.column))
        .map(|point| (point.position - anchor.position).length())
        .filter(|distance| distance.is_finite() && *distance > f32::EPSILON)
        .min_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal))
        .unwrap_or(1.0);

    let targets: Vec<_> = selected_points
        .into_iter()
        .filter_map(|point| {
            let weight = if soft_pull {
                if (point.row, point.column) == (anchor.row, anchor.column) {
                    1.0
                } else {
                    surface_soft_pull_weight(
                        (point.position - anchor.position).length(),
                        reference_distance,
                    )
                }
            } else {
                1.0
            };
            let target = quantize_surface_drag_value(
                point.value + delta * weight,
                conversion,
                integer_storage,
            );
            (target.is_finite() && (target - point.value).abs() > f64::EPSILON).then_some((
                point.row,
                point.column,
                target,
            ))
        })
        .collect();
    (!targets.is_empty()).then_some(targets)
}

fn quantize_surface_drag_value(
    value: f64,
    conversion: Option<&Conversion>,
    integer_storage: bool,
) -> f64 {
    if !integer_storage {
        return value;
    }
    let Some(conversion) = conversion else {
        return value;
    };
    let Some(raw) = conversion.invert(value).ok() else {
        return value;
    };
    conversion.evaluate(raw.round()).unwrap_or(value)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TableArrangeMode {
    Cascade,
    Tile,
    Reset,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ScrollFrameKind {
    Browser,
    Inspector,
    Table,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ScrollFramePolicy {
    horizontal: bool,
    vertical: bool,
    auto_shrink: [bool; 2],
}

const fn scroll_frame_policy(kind: ScrollFrameKind) -> ScrollFramePolicy {
    match kind {
        ScrollFrameKind::Browser | ScrollFrameKind::Inspector => ScrollFramePolicy {
            horizontal: true,
            vertical: true,
            auto_shrink: [false, false],
        },
        ScrollFrameKind::Table => ScrollFramePolicy {
            horizontal: true,
            vertical: true,
            auto_shrink: [false, false],
        },
    }
}

impl ScrollFramePolicy {
    fn scroll_area(self) -> egui::ScrollArea {
        let area = match (self.horizontal, self.vertical) {
            (true, true) => egui::ScrollArea::both(),
            (false, true) => egui::ScrollArea::vertical(),
            (true, false) => egui::ScrollArea::horizontal(),
            (false, false) => egui::ScrollArea::vertical(),
        };
        area.auto_shrink(self.auto_shrink)
    }
}

fn table_key(xdf_fingerprint: &str, semantic_id: &str) -> String {
    format!("{xdf_fingerprint}|{semantic_id}")
}

fn collect_category_keys(nodes: &[CategoryNode], output: &mut Vec<String>) {
    for node in nodes {
        output.push(node.key.clone());
        collect_category_keys(&node.children, output);
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum BrowserAction {
    Open(String),
    ToggleFavorite(String),
    ToggleCategory { key: String, collapsed: bool },
}

fn sort_category_node_contents(
    node: &mut CategoryNode,
    sort_key: CatalogSortKey,
    direction: SortDirection,
    organization: BrowserOrganization,
    fingerprint: Option<&str>,
    favorite_keys: &[String],
    recent_keys: &[String],
) {
    sort_summaries(
        &mut node.parameters,
        sort_key,
        direction,
        favorite_keys,
        recent_keys,
    );
    if organization != BrowserOrganization::Categories {
        node.parameters.sort_by_key(|summary| {
            summary_organization_rank(
                summary,
                organization,
                fingerprint,
                favorite_keys,
                recent_keys,
            )
        });
    }
    for child in &mut node.children {
        sort_category_node_contents(
            child,
            sort_key,
            direction,
            organization,
            fingerprint,
            favorite_keys,
            recent_keys,
        );
    }
    if organization != BrowserOrganization::Categories {
        node.children.sort_by_key(|child| {
            category_organization_rank(child, organization, fingerprint, favorite_keys, recent_keys)
        });
    }
}

fn category_organization_rank(
    node: &CategoryNode,
    organization: BrowserOrganization,
    fingerprint: Option<&str>,
    favorite_keys: &[String],
    recent_keys: &[String],
) -> usize {
    let direct = node.parameters.iter().map(|summary| {
        summary_organization_rank(
            summary,
            organization,
            fingerprint,
            favorite_keys,
            recent_keys,
        )
    });
    let nested = node.children.iter().map(|child| {
        category_organization_rank(child, organization, fingerprint, favorite_keys, recent_keys)
    });
    direct.chain(nested).min().unwrap_or(usize::MAX)
}

fn summary_organization_rank(
    summary: &ParameterSummary,
    organization: BrowserOrganization,
    fingerprint: Option<&str>,
    favorite_keys: &[String],
    recent_keys: &[String],
) -> usize {
    let Some(fingerprint) = fingerprint else {
        return usize::MAX;
    };
    let key = table_key(fingerprint, &summary.semantic_id);
    match organization {
        BrowserOrganization::Categories => 0,
        BrowserOrganization::FavoritesFirst => {
            if favorite_keys.iter().any(|favorite| favorite == &key) {
                0
            } else {
                1
            }
        }
        BrowserOrganization::RecentFirst => recent_keys
            .iter()
            .position(|recent| recent == &key)
            .unwrap_or(recent_keys.len() + 1),
    }
}

fn render_browser_parameter_row(
    ui: &mut egui::Ui,
    summary: &ParameterSummary,
    key: Option<&str>,
    favorites: &[String],
    selected_semantic_id: Option<&str>,
    actions: &mut Vec<BrowserAction>,
    school_me_mode: bool,
) {
    let favorite = key.is_some_and(|key| favorites.iter().any(|item| item == key));
    let selected = selected_semantic_id == Some(summary.semantic_id.as_str());
    ui.horizontal(|ui| {
        if let Some(key) = key {
            let response = ui.small_button(if favorite { "★" } else { "☆" });
            if school_me_mode {
                school_help::show_custom_for_response(
                    ui.ctx(),
                    &response,
                    true,
                    school_help::SchoolHelpId::BrowserFavorite,
                );
            } else {
                response.clone().on_hover_text(if favorite {
                    "Remove from favorites"
                } else {
                    "Add to favorites"
                });
            }
            if response.clicked() {
                actions.push(BrowserAction::ToggleFavorite(key.to_string()));
            }
        }
        let response = ui.selectable_label(selected, summary_label(summary));
        if school_me_mode {
            school_help::show_custom_for_response(
                ui.ctx(),
                &response,
                true,
                school_help::SchoolHelpId::BrowserParameter,
            );
        } else {
            response.clone().on_hover_text(format!(
                "{}\npath: {}\naddress: 0x{:X}\nsemantic ID: {}",
                summary.title,
                summary.category_path.join(" › "),
                summary.address,
                summary.semantic_id
            ));
        }
        if response.clicked() {
            actions.push(BrowserAction::Open(summary.semantic_id.clone()));
        }
    });
}

fn render_favorite_section(
    ui: &mut egui::Ui,
    nodes: &[CategoryNode],
    project_scope: &str,
    fingerprint: &str,
    favorites: &[String],
    selected_semantic_id: Option<&str>,
    actions: &mut Vec<BrowserAction>,
    school_me_mode: bool,
) {
    let response = egui::CollapsingHeader::new("Favorites")
        .id_salt(("parameter-favorites", project_scope, fingerprint))
        .default_open(true)
        .show(ui, |ui| {
            let mut seen = BTreeSet::new();
            let count = render_favorite_parameters_in_nodes(
                ui,
                nodes,
                fingerprint,
                favorites,
                selected_semantic_id,
                actions,
                &mut seen,
                school_me_mode,
            );
            if count == 0 {
                ui.weak("No favorite parameters match this filter.");
            }
        });
    school_help::show_custom_for_response(
        ui.ctx(),
        &response.header_response,
        school_me_mode,
        school_help::SchoolHelpId::BrowserFavorite,
    );
}

fn render_favorite_parameters_in_nodes(
    ui: &mut egui::Ui,
    nodes: &[CategoryNode],
    fingerprint: &str,
    favorites: &[String],
    selected_semantic_id: Option<&str>,
    actions: &mut Vec<BrowserAction>,
    seen: &mut BTreeSet<String>,
    school_me_mode: bool,
) -> usize {
    let mut count = 0;
    for node in nodes {
        for summary in &node.parameters {
            let key = table_key(fingerprint, &summary.semantic_id);
            if favorites.iter().any(|favorite| favorite == &key)
                && seen.insert(summary.semantic_id.clone())
            {
                render_browser_parameter_row(
                    ui,
                    summary,
                    Some(&key),
                    favorites,
                    selected_semantic_id,
                    actions,
                    school_me_mode,
                );
                count += 1;
            }
        }
        count += render_favorite_parameters_in_nodes(
            ui,
            &node.children,
            fingerprint,
            favorites,
            selected_semantic_id,
            actions,
            seen,
            school_me_mode,
        );
    }
    count
}

fn render_category_node(
    ui: &mut egui::Ui,
    node: &CategoryNode,
    project_scope: &str,
    fingerprint: Option<&str>,
    favorites: &[String],
    collapsed_categories: &[String],
    selected_semantic_id: Option<&str>,
    actions: &mut Vec<BrowserAction>,
    school_me_mode: bool,
) {
    let was_collapsed = collapsed_categories.iter().any(|key| key == &node.key);
    let header = egui::CollapsingHeader::new(format!("{} ({})", node.name, node.total_count))
        .id_salt(("parameter-category", project_scope, node.key.as_str()))
        .default_open(!was_collapsed)
        .show(ui, |ui| {
            for summary in &node.parameters {
                let key =
                    fingerprint.map(|fingerprint| table_key(fingerprint, &summary.semantic_id));
                render_browser_parameter_row(
                    ui,
                    summary,
                    key.as_deref(),
                    favorites,
                    selected_semantic_id,
                    actions,
                    school_me_mode,
                );
            }
            for child in &node.children {
                render_category_node(
                    ui,
                    child,
                    project_scope,
                    fingerprint,
                    favorites,
                    collapsed_categories,
                    selected_semantic_id,
                    actions,
                    school_me_mode,
                );
            }
        });
    school_help::show_custom_for_response(
        ui.ctx(),
        &header.header_response,
        school_me_mode,
        school_help::SchoolHelpId::CategoryExpandCollapse,
    );
    if header.header_response.clicked() {
        actions.push(BrowserAction::ToggleCategory {
            key: node.key.clone(),
            collapsed: was_collapsed,
        });
    }
}

fn category_header_id(parent_ui_id: egui::Id, project_scope: &str, category_key: &str) -> egui::Id {
    // `CollapsingHeader::show` creates a child UI before it applies `id_salt`.
    // Reproduce that stable-ID step so saved project state can also update egui's
    // already-persisted widget state, including headers that are currently hidden
    // below a collapsed ancestor.
    parent_ui_id
        .with(egui::IdSalt::new("child"))
        .with(egui::IdSalt::new((
            "parameter-category",
            project_scope,
            category_key,
        )))
}

fn category_body_ui_id(parent_ui_id: egui::Id, header_id: egui::Id) -> egui::Id {
    // `show_body_indented` creates a child scope and then an indented child UI.
    parent_ui_id
        .with(egui::IdSalt::new("child"))
        .with(egui::IdSalt::new("child"))
        .with(egui::IdSalt::new(header_id))
}

fn sync_category_header_state(context: &egui::Context, header_id: egui::Id, should_open: bool) {
    let mut state = egui::collapsing_header::CollapsingState::load_with_default_open(
        context,
        header_id,
        should_open,
    );
    state.set_open(should_open);
    state.store(context);
}

fn sync_category_header_states(
    context: &egui::Context,
    parent_ui_id: egui::Id,
    nodes: &[CategoryNode],
    project_scope: &str,
    collapsed_categories: &[String],
) {
    for node in nodes {
        let header_id = category_header_id(parent_ui_id, project_scope, &node.key);
        let should_open = !collapsed_categories.iter().any(|key| key == &node.key);
        sync_category_header_state(context, header_id, should_open);

        sync_category_header_states(
            context,
            category_body_ui_id(parent_ui_id, header_id),
            &node.children,
            project_scope,
            collapsed_categories,
        );
    }
}

