                                    school_help::show_custom_for_response(ui.ctx(), &rows, school_me_mode, school_help::SchoolHelpId::XdfStorage);
                                    changed |= rows.changed();
                                    ui.label("Columns:");
                                    let columns = ui.add(egui::DragValue::new(&mut self.xdf_editor.form.definition.dimensions.columns).range(1..=512));
                                    school_help::show_custom_for_response(ui.ctx(), &columns, school_me_mode, school_help::SchoolHelpId::XdfStorage);
                                    changed |= columns.changed();
                                    let column_major = ui.checkbox(&mut self.xdf_editor.form.definition.column_major, "Column major");
                                    school_help::show_custom_for_response(ui.ctx(), &column_major, school_me_mode, school_help::SchoolHelpId::XdfStorage);
                                    changed |= column_major.changed();
