#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ParsedShortcut {
    ctrl: bool,
    alt: bool,
    shift: bool,
    key: egui::Key,
}

fn shortcut_matches(input: &egui::InputState, source: &str) -> bool {
    let Some(shortcut) = parse_shortcut(source) else {
        return false;
    };
    let modifiers_match = |modifiers: egui::Modifiers| {
        shortcut.ctrl == modifiers.ctrl
            && shortcut.alt == modifiers.alt
            && shortcut.shift == modifiers.shift
    };
    let logical_key_pressed = modifiers_match(input.modifiers) && input.key_pressed(shortcut.key);
    let physical_digit_pressed = is_digit_key(shortcut.key)
        && input.events.iter().any(|event| match event {
            egui::Event::Key {
                physical_key: Some(key),
                pressed: true,
                repeat: false,
                modifiers,
                ..
            } => *key == shortcut.key && modifiers_match(*modifiers),
            _ => false,
        });
    logical_key_pressed || physical_digit_pressed
}

fn is_digit_key(key: egui::Key) -> bool {
    matches!(
        key,
        egui::Key::Num0
            | egui::Key::Num1
            | egui::Key::Num2
            | egui::Key::Num3
            | egui::Key::Num4
            | egui::Key::Num5
            | egui::Key::Num6
            | egui::Key::Num7
            | egui::Key::Num8
            | egui::Key::Num9
    )
}

fn parse_shortcut(source: &str) -> Option<ParsedShortcut> {
    let mut ctrl = false;
    let mut alt = false;
    let mut shift = false;
    let mut key = None;
    for token in source
        .split('+')
        .map(str::trim)
        .filter(|token| !token.is_empty())
    {
        match token.to_ascii_uppercase().as_str() {
            "CTRL" | "CONTROL" => ctrl = true,
            "ALT" => alt = true,
            "SHIFT" => shift = true,
            value => key = Some(parse_key(value)?),
        }
    }
    Some(ParsedShortcut {
        ctrl,
        alt,
        shift,
        key: key?,
    })
}

fn shortcut_text_for_key(key: egui::Key, modifiers: egui::Modifiers) -> Option<String> {
    let debug_name = format!("{key:?}");
    let key_name = debug_name.strip_prefix("Num").unwrap_or(&debug_name);
    parse_key(&key_name.to_ascii_uppercase())?;

    let mut parts = Vec::with_capacity(4);
    if modifiers.ctrl {
        parts.push("Ctrl".to_string());
    }
    if modifiers.alt {
        parts.push("Alt".to_string());
    }
    if modifiers.shift {
        parts.push("Shift".to_string());
    }
    parts.push(key_name.to_string());
    Some(parts.join("+"))
}

fn shortcut_conflict(
    descriptors: &[CommandDescriptor],
    overrides: &BTreeMap<String, String>,
    edited_command_id: &str,
    candidate: &str,
) -> Option<String> {
    let candidate = parse_shortcut(candidate)?;
    descriptors.iter().find_map(|descriptor| {
        if descriptor.id == edited_command_id {
            return None;
        }
        let binding = match overrides.get(&descriptor.id) {
            Some(value) if value.trim().is_empty() => None,
            Some(value) => Some(value.as_str()),
            None => descriptor.default_shortcut.as_deref(),
        }?;
        (parse_shortcut(binding) == Some(candidate)).then(|| descriptor.id.clone())
    })
}

fn parse_key(value: &str) -> Option<egui::Key> {
    Some(match value {
        "0" => egui::Key::Num0,
        "1" => egui::Key::Num1,
        "2" => egui::Key::Num2,
        "3" => egui::Key::Num3,
        "4" => egui::Key::Num4,
        "5" => egui::Key::Num5,
        "6" => egui::Key::Num6,
        "7" => egui::Key::Num7,
        "8" => egui::Key::Num8,
        "9" => egui::Key::Num9,
        "A" => egui::Key::A,
        "B" => egui::Key::B,
        "C" => egui::Key::C,
        "D" => egui::Key::D,
        "E" => egui::Key::E,
        "F" => egui::Key::F,
        "G" => egui::Key::G,
        "H" => egui::Key::H,
        "I" => egui::Key::I,
        "J" => egui::Key::J,
        "K" => egui::Key::K,
        "L" => egui::Key::L,
        "M" => egui::Key::M,
        "N" => egui::Key::N,
        "O" => egui::Key::O,
        "P" => egui::Key::P,
        "Q" => egui::Key::Q,
        "R" => egui::Key::R,
        "S" => egui::Key::S,
        "T" => egui::Key::T,
        "U" => egui::Key::U,
        "V" => egui::Key::V,
        "W" => egui::Key::W,
        "X" => egui::Key::X,
        "Y" => egui::Key::Y,
        "Z" => egui::Key::Z,
        "ENTER" | "RETURN" => egui::Key::Enter,
        "SPACE" => egui::Key::Space,
        "TAB" => egui::Key::Tab,
        "ESC" | "ESCAPE" => egui::Key::Escape,
        "F1" => egui::Key::F1,
        "F2" => egui::Key::F2,
        "F3" => egui::Key::F3,
        "F4" => egui::Key::F4,
        "F5" => egui::Key::F5,
        "F6" => egui::Key::F6,
        "F7" => egui::Key::F7,
        "F8" => egui::Key::F8,
        "F9" => egui::Key::F9,
        "F10" => egui::Key::F10,
        "F11" => egui::Key::F11,
        "F12" => egui::Key::F12,
        _ => return None,
    })
}

impl eframe::App for TunerApp {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        let viewport_rect = ui.max_rect();
        let context = ui.ctx().clone();
        self.apply_visual_preferences(ui);
        self.poll_ui_ipc(&context);
        self.poll_background_operations(&context);
        self.handle_shortcuts(&context);
        if self.preferences.show_editor
            && self
                .pending_grid_paste_table
                .as_deref()
                .is_some_and(|key| self.open_tables.iter().any(|table| table.key == key))
        {
            context.send_viewport_cmd(egui::ViewportCommand::RequestPaste);
        }
        let toolbar = egui::Panel::top("toolbar").show(ui, |ui| self.show_toolbar(ui));
        let mut diagnostics_rect = None;
        if self.preferences.show_diagnostics {
            let project_scope = self.project_scope();
            let diagnostics =
                egui::Panel::bottom(egui::Id::new(("diagnostics", project_scope.as_str())))
                    .resizable(true)
                    .default_size(self.preferences.diagnostics_height as f32)
                    .show(ui, |ui| self.show_diagnostics(ui));
            diagnostics_rect = Some(diagnostics.response.rect);
            if let Some(state) = egui::PanelState::load(
                ui.ctx(),
                egui::Id::new(("diagnostics", project_scope.as_str())),
            ) {
                let height = state.size().y.round().clamp(80.0, 600.0) as u32;
                if self.preferences.diagnostics_height != height {
                    self.preferences.diagnostics_height = height;
                    self.preferences_dirty = true;
                }
            }
        }
        let dock = egui::Panel::bottom("window-dock")
            .resizable(false)
            .default_size(38.0)
            .show(ui, |ui| self.show_window_dock(ui));
        self.tool_window_bounds = Some(window_geometry::shell_safe_rect(
            viewport_rect,
            toolbar.response.rect,
            dock.response.rect,
            diagnostics_rect,
        ));
        self.show_workspace_dialog(&context);
        if self.preferences.show_browser {
            self.show_browser(ui);
        }
        if self.preferences.show_inspector {
            self.show_inspector(ui);
        }
        let central = egui::CentralPanel::default().show(ui, |ui| {
            if self.preferences.show_editor {
                self.show_workspace_canvas(ui, &context);
            } else {
                ui.vertical_centered(|ui| {
                    ui.add_space(80.0);
                    ui.heading("Editor hidden");
                    ui.label("Use View → Panels or the command palette to show it.");
                });
            }
        });
        self.initial_window_bounds = Some(central.response.rect);
        if self.preferences.show_editor {
            let canvas_rect = central.response.rect;
            let table_bounds = self.tool_window_bounds.unwrap_or(canvas_rect);
            let keys: Vec<_> = self
                .open_tables
                .iter()
                .map(|table| table.key.clone())
                .collect();
            for key in keys {
                if !self
                    .project_preferences
                    .dock_state
                    .is_minimized(&WindowId::Table(key.clone()))
                {
                    self.show_table_window(&context, table_bounds, &key);
                }
            }
            self.show_surface_windows(&context, canvas_rect);
        }
        if !self
            .project_preferences
            .dock_state
            .is_minimized(&WindowId::Compare)
        {
            self.show_compare_window(&context);
        }
        if !self
            .project_preferences
            .dock_state
            .is_minimized(&WindowId::CompareSurface)
        {
            self.show_compare_surface(&context);
        }
        if !self
            .project_preferences
            .dock_state
            .is_minimized(&WindowId::HexEditor)
        {
            self.show_hex_editor(&context, central.response.rect);
        }
        if !self
            .project_preferences
            .dock_state
            .is_minimized(&WindowId::MapFinder)
        {
            self.show_map_finder(&context, central.response.rect);
        }
        self.show_xdf_editor_window(&context, central.response.rect);
        self.show_action_history_window(&context);
        if !self
            .project_preferences
            .dock_state
            .is_minimized(&WindowId::Search)
        {
            self.show_search_window(&context, central.response.rect);
        }
        self.show_command_palette(&context);
        self.show_debug_report(&context);
        self.show_settings(&context);
        self.show_nooklink_setup(&context);
        self.show_project_notepad_window(&context);
        self.show_startup_restore_prompt(&context);
        self.show_xdf_reuse_prompt(&context);
        if !school_help::show_help_window(&context, self.preferences.school_me_mode) {
            self.preferences.school_me_mode = false;
            self.preferences_dirty = true;
        }
        self.show_operation_overlay(&context, central.response.rect);
        self.raise_debug_report(&context);
        self.raise_focused_dock_window(&context);
        if let Some(text) = self.pending_clipboard_text.take() {
            context.copy_text(text);
        }
        self.flush_preferences_if_idle(&context);
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        self.persist_preferences();
    }
}

